from pathlib import Path
import json,hashlib,shutil,xml.etree.ElementTree as E,sys
b=Path(__file__).resolve().parent.parent
run=Path('/tmp/lor-event-detail-edges-r3')/(sys.argv[1] if len(sys.argv)>1 else 'Verify01')
for runname in sorted({p.name for p in run.parent.glob('Verify*') if p.is_dir()}):
 for mode in ['Import','EditMode','PlayMode']:
  dest=b/'QA'/runname/mode;dest.mkdir(parents=True,exist_ok=True)
  for name in ['command.json','unity.log','results.xml']:
   p=run.parent/runname/mode/name
   if p.exists():shutil.copyfile(p,dest/name)
cap=b/'UnityCaptures';cap.mkdir(exist_ok=True)
for p in (run/'EventDetail').glob('*'):shutil.copyfile(p,cap/p.name)
shutil.copyfile('ProjectDocs/AI/EventDetailReferenceRebuild/OriginalReferenceR2/UnityCaptures/EventDetail_941x1672_RU.png',b/'QA/PreviousEventDetail.png')
shutil.copyfile('ProjectDocs/AI/EventsReferenceRebuild/TabsAndFooterR4/UnityCaptures/Events_941x1672_RU.png',b/'QA/ApprovedEventsStyle.png')
shutil.copyfile('ProjectDocs/AI/EventDetailReferenceRebuild/R1/Sources/OriginalEventDetailReference.png',b/'Sources/OriginalReference.png')
choices=[('UnityCaptures/EventDetail_941x1672_RU.png','Implemented — Russian'),('UnityCaptures/EventDetail_941x1672_EN.png','Implemented — English'),('UnityCaptures/EventDetail_576x1280_safe_RU.png','Narrow phone — Russian'),('UnityCaptures/EventDetail_576x1280_safe_EN.png','Narrow phone — English'),('UnityCaptures/EventDetail_1080x2400_safe_RU.png','Tall phone — safe area'),('UnityCaptures/EventDetail_MaxBalances_RU.png','Maximum balances'),('Sources/OriginalReference.png','Dedicated original — Firebird Festival'),('QA/PreviousEventDetail.png','Previous R2 — before edge/frame repairs'),('QA/ApprovedEventsStyle.png','Events R4 — shared style context')]
options=''.join(f'<option value="{p}">{label}</option>' for p,label in choices)
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Event Detail — Edges and Ornamentation R3</title><style>body{background:#0a101a;color:#eeddb5;font:16px/1.5 system-ui;margin:24px auto;max-width:960px;padding:0 16px}h1{font-size:26px}a{color:#9bcded}select{max-width:100%;padding:10px;background:#14263a;color:#f6e4b6;border:1px solid #90713f;font:inherit}.page{display:block;width:min(100%,471px);height:auto;margin:20px auto;border:1px solid #78603b}.note{color:#c3c9d0}button{font:inherit;padding:8px;background:#213146;color:#ffe8b6;border:1px solid #89704a;cursor:pointer}</style><h1>Event Detail — Edges and Ornamentation R3</h1><p>Actual Unity implementation: repaired original Firebird silhouette and source highlights, restored countdown plaque, feather balance frame and premium reward enclosure. Original Russian title/buttons and the shared Home header/background are retained.</p><p class="note">The shared Home header/background remain. Event dates, counts, thresholds and scores are unconfirmed and shown as unavailable. Rewards and leaderboard are previews; Play and Activate are disabled. English uses localized live lettering.</p><label>View <select id="view">OPTIONS</select></label> <button id="original">Compare with original</button><img id="page" class="page" src="UnityCaptures/EventDetail_941x1672_RU.png" alt="Selected portrait Event Detail page"><p id="caption" class="note">Actual Unity Play Mode capture; isolated test save and simulated screen/safe area.</p><p><a href="ImplementationReport.md">Implementation and verification</a> · <a href="QA/ReferenceFidelityReview.md">Remaining differences</a> · <a href="QA/countdown_alpha.png">Countdown alpha inspection</a> · <a href="QA/firebird_alpha.png">Firebird alpha inspection</a> · <a href="QA/premium_inset_alpha.png">Premium frame alpha inspection</a></p><script>const picker=document.querySelector('#view'),page=document.querySelector('#page'),caption=document.querySelector('#caption');let previous=picker.value;function show(){page.src=picker.value;caption.textContent=picker.value.includes('OriginalReference')?'Dedicated original Event Detail reference.':picker.value.includes('PreviousEventDetail')?'Historical R2 capture — before feather and ornament corrections.':picker.value.includes('ApprovedEventsStyle')?'Events R4 native capture — shared style context.':'Actual Unity Play Mode capture; isolated save and simulated screen/safe area.';}picker.onchange=show;document.querySelector('#original').onclick=()=>{if(picker.value.includes('OriginalReference'))picker.value=previous;else{previous=picker.value;picker.value='Sources/OriginalReference.png';}show();};</script></html>'''.replace('OPTIONS',options)
(b/'EventDetail_EdgesAndOrnaments_R3_Review.html').write_text(html)
before=json.loads((b/'Sources/BeforeAssetsHashes.json').read_text());after={str(p):hashlib.sha256(p.read_bytes()).hexdigest() for p in Path('Assets').rglob('*') if p.is_file()}
record={'modified':sorted(p for p in before.keys()&after.keys() if before[p]!=after[p]),'added':sorted(after.keys()-before.keys()),'deleted':sorted(before.keys()-after.keys()),'checks':{}}
for mode in ['EditMode','PlayMode']:
 r=E.parse(run/mode/'results.xml').getroot();record['checks'][mode]={k:r.get(k) for k in ['result','passed','failed','skipped','total']}
(b/'QA/ScopeAndVerification.json').write_text(json.dumps(record,indent=2)+'\n');print(json.dumps({**record,'added':len(record['added'])},indent=2))
